    const s = mem()
    const legacy = addCard(emptyBoard(), 'todo', input('A'), 'a')
    saveBoard(legacy, s)
    const ws = updateActiveBoard(loadWorkspace(s), (b) => addCard(b, 'todo', input('New'), 'n'))
